#!/usr/bin/env python3
"""SPATIAL MANIFOLD v3 — maximum interactive visual change surface.
Everything from v2 (glow, trails, pulses, shockwave, gyro, haptics, sparkline,
ticker) plus: 4 morphing layouts (sphere / spiral / ring / strata-sphere),
6 color schemes, edge styles (line/arc/dash), edge color modes, class filters
(clean/wider/floor), never-pair overlay, node shapes + label modes, mesh
density, starfield, trail & glow & speed sliders, back-face cull (X-RAY),
W-spectrum ribbon, guided tour of the sinks, touch ripples. Data asserted."""
import json, math

D = json.load(open('/home/hatch/workspace/your_files/hybrid_filing/core_compact.json'))
nodes, pairs, never, spec = D['nodes'], D['pairs'], D['never'], D['spectrumW']
assert D['totals'] == {'doors': 7140, 'door_pairs': 944, 'never_pairs': 184,
                       'clean': 360, 'wider': 3584, 'floor': 3196}
assert {n['m']: n for n in nodes}[31]['sink'] == 162 and len(never) == 184

GA = math.pi * (3 - math.sqrt(5))
N3D = []
for i, n in enumerate(nodes):
    y = 1 - (i / (len(nodes) - 1)) * 2
    rad = math.sqrt(max(0.0, 1 - y * y))
    th = GA * i
    # flat spiral (phyllotaxis), ring, layouts normalized to ~unit extent
    fr = 0.115 * math.sqrt(i + 1)
    fa = i * 2.39996322972865332
    ra = i / len(nodes) * 2 * math.pi
    N3D.append({'m': n['m'],
                'sph': [round(math.cos(th) * rad, 4), round(y, 4), round(math.sin(th) * rad, 4)],
                'flat': [round(math.cos(fa) * fr, 4), round(math.sin(fa) * fr, 4), 0],
                'ring': [round(math.cos(ra) * 1.02, 4), round(math.sin(ra) * 1.02, 4), 0],
                'r': 0.72 + 0.55 * (n['appear'] / 648.0), 'pc': bin(n['m']).count('1'),
                'hall': n['hall'], 'sink': n['sink'], 'pairm': n['pairm'], 'appear': n['appear']})
E3 = [[p['a'], p['b'], p['dist'], p['doors'], p['clean'], p['wider'], p['floor']] for p in pairs]
NV = [[p['a'], p['b'], p['dist']] for p in never]
TOP = sorted(E3, key=lambda e: -e[3])[:28]

html = r"""<!DOCTYPE html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1, maximum-scale=1, user-scalable=no">
<title>Spatial Manifold — The 7,140-Door System</title>
<style>
 html,body{margin:0;height:100%;background:#000;overflow:hidden;font-family:ui-monospace,Menlo,monospace;color:#cfe3ff;-webkit-user-select:none;user-select:none}
 #cv{position:fixed;inset:0;width:100%;height:100%;display:block;touch-action:none}
 .hud{position:fixed;top:14px;left:16px;font-size:12.5px;line-height:1.8;letter-spacing:.06em;color:#7fb2ff;text-shadow:0 0 6px #123;pointer-events:none;white-space:pre;z-index:3}
 #spark{position:fixed;top:118px;left:16px;pointer-events:none;z-index:3;opacity:.9}
 .cap{position:fixed;left:16px;bottom:172px;font-family:Georgia,serif;font-style:italic;font-size:14.5px;color:#e8e6df;max-width:72vw;pointer-events:none;z-index:3}
 .tick{position:fixed;left:16px;bottom:148px;font-size:11.5px;color:#5b7bb5;pointer-events:none;z-index:3;letter-spacing:.05em}
 .bar{position:fixed;top:12px;right:12px;display:flex;flex-direction:column;gap:8px;align-items:flex-end;z-index:5}
 button{background:rgba(10,18,38,.88);color:#cfe3ff;border:1px solid #3a5a9c;border-radius:8px;padding:8px 12px;font-family:ui-monospace,Menlo,monospace;font-size:12.5px;cursor:pointer}
 button.gold{border-color:#c9a227;color:#f3e9c8;font-size:15px;padding:11px 18px}
 button.on{border-color:#c9a227;color:#f3e9c8}
 #state{font-size:12.5px;color:#f3e9c8;text-align:right;max-width:62vw}
 #readout{position:fixed;right:12px;bottom:172px;background:rgba(8,12,26,.92);border:1px solid #c9a227;border-radius:9px;padding:11px 15px;font-family:Georgia,serif;font-size:14.5px;color:#e8e6df;max-width:76vw;display:none;z-index:5}
 #readout .bar2{height:5px;background:#c9a227;border-radius:3px;margin-top:6px}
 #tray{position:fixed;left:0;right:0;bottom:0;z-index:6;background:rgba(5,8,18,.94);border-top:1px solid #2a3554;padding:8px 10px 12px;max-height:150px;overflow-y:auto;transition:transform .35s}
 #tray.hidden{transform:translateY(110%)}
 .trow{display:flex;gap:6px;align-items:center;margin:4px 0;flex-wrap:nowrap;overflow-x:auto;padding-bottom:2px}
 .tlab{font-size:10.5px;color:#5b7bb5;letter-spacing:.12em;min-width:62px}
 .trow button{white-space:nowrap;padding:6px 10px;font-size:12px}
 input[type=range]{accent-color:#c9a227;width:110px}
 #trayBtn{position:fixed;right:12px;bottom:162px;z-index:7;border-color:#c9a227;color:#f3e9c8}
 #deckBtn{position:fixed;left:12px;bottom:162px;z-index:7;border-color:#c9a227;color:#f3e9c8}
 #deck{position:fixed;left:10px;top:176px;bottom:196px;width:248px;z-index:5;overflow-y:auto;display:none;padding-right:2px}
 #deck.open{display:block}
 .mcard{background:rgba(8,12,26,.92);border:1px solid #2a3554;border-left:3px solid #c9a227;border-radius:8px;padding:9px 11px;margin-bottom:8px}
 .mtitle{font-size:11px;letter-spacing:.1em;color:#f3e9c8;margin-bottom:5px}
 .mbody{font-family:Georgia,serif;font-size:12.8px;line-height:1.5;color:#cfd6e4}
 .mcard svg{margin-top:6px;max-width:100%}
 #boot{position:fixed;inset:0;background:#000;z-index:9;display:flex;align-items:center;justify-content:center;flex-direction:column;gap:8px;transition:opacity .7s}
 #crt{position:fixed;inset:0;pointer-events:none;z-index:8;display:none;background:repeating-linear-gradient(0deg, rgba(0,0,0,0.16) 0 1px, transparent 1px 3px)}
 #vig{position:fixed;inset:0;pointer-events:none;z-index:8;display:none;background:radial-gradient(ellipse at center, transparent 52%, rgba(0,0,0,0.55) 100%)}
 .corner{position:fixed;width:26px;height:26px;z-index:4;pointer-events:none;border:0 solid #c9a227;opacity:.65}
 #boot div{font-size:13px;letter-spacing:.14em;color:#7fb2ff}
 #boot .g{color:#f3e9c8;font-size:19px}
</style></head><body>
<canvas id="cv"></canvas>
<div id="crt"></div><div id="vig"></div>
<div class="corner" style="top:8px;left:8px;border-top-width:2px;border-left-width:2px"></div>
<div class="corner" style="top:8px;right:8px;border-top-width:2px;border-right-width:2px"></div>
<div class="corner" style="bottom:158px;left:8px;border-bottom-width:2px;border-left-width:2px"></div>
<div class="corner" style="bottom:158px;right:8px;border-bottom-width:2px;border-right-width:2px"></div>
<div class="hud" id="hud"></div>
<canvas id="spark" width="150" height="30"></canvas>
<div class="cap">You are looking at a flat shadow of the 7,140-door system.</div>
<div class="tick" id="tick"></div>
<div class="bar">
 <button class="gold" id="gyroBtn">ENABLE GYRO</button>
 <div id="state">GYRO OFF — drag to orbit · pinch to zoom · tap a node · tap ★ to ring the system</div>
</div>
<div id="readout"></div>
<button id="trayBtn">VISUAL CONTROLS ▾</button>
<button id="deckBtn">◉ EVERYTHING MEASURED</button>
<div id="deck"><div class="mcard"><div class="mtitle">DEFAULT STATE — THE MEASURED UNIVERSE</div><div class="mbody">On load, the object runs at the system’s exact speed ratio and wears its measured shape. THE RATIO: the two operators’ total spectral energies are the integers 685,584 (T, flow) and 191,808 (W, structure) — their ratio reduces to exactly <b>529 : 148</b>. The manifold’s spin is the unit; the frame cage turns at 148/529 of it; the core solid and the flow pulses run at 529/148 of it. THE SHAPE: node radii are the measured appearances themselves, and the skin carries the curvature law’s constant-width preference as a three-lobed field. The frame around all this — “every observable universe in galaxy” — is the frame you chose; everything inside it is the system’s own exact arithmetic.</div></div>
<div class="mcard"><div class="mtitle">DOOR CENSUS — THE INSIDE TOTAL</div><div class="mbody">7,140 doors · 944 door-pairs · 184 never-pairs · 12,528 flow transitions closing exactly.</div><svg width="200" height="44" viewBox="0 0 200 44"><rect x="1.0" y="40.8" width="64.7" height="3.2" fill="#c9a227" opacity="0.85"/><text x="33.3" y="43" fill="#9aa3b8" font-size="7.5" text-anchor="middle">CLEAN 360</text><rect x="67.7" y="12.0" width="64.7" height="32.0" fill="#c9a227" opacity="0.85"/><text x="100.0" y="43" fill="#9aa3b8" font-size="7.5" text-anchor="middle">WIDER 3584</text><rect x="134.3" y="15.5" width="64.7" height="28.5" fill="#c9a227" opacity="0.85"/><text x="166.7" y="43" fill="#9aa3b8" font-size="7.5" text-anchor="middle">FLOOR 3196</text></svg></div>
<div class="mcard"><div class="mtitle">DISTANCE CENSUS</div><div class="mbody">Pairs by distance 1–6: 124 / 282 / 352 / 253 / 100 / 17. Doors live only at 2–6. The 124 distance-1 pairs are the gap — zero doors.</div><svg width="200" height="44" viewBox="0 0 200 44"><rect x="1.0" y="37.9" width="38.0" height="6.1" fill="#a8e6b0" opacity="0.85"/><text x="20.0" y="43" fill="#9aa3b8" font-size="7.5" text-anchor="middle">d2</text><rect x="41.0" y="22.7" width="38.0" height="21.3" fill="#a8e6b0" opacity="0.85"/><text x="60.0" y="43" fill="#9aa3b8" font-size="7.5" text-anchor="middle">d3</text><rect x="81.0" y="12.0" width="38.0" height="32.0" fill="#a8e6b0" opacity="0.85"/><text x="100.0" y="43" fill="#9aa3b8" font-size="7.5" text-anchor="middle">d4</text><rect x="121.0" y="20.6" width="38.0" height="23.4" fill="#a8e6b0" opacity="0.85"/><text x="140.0" y="43" fill="#9aa3b8" font-size="7.5" text-anchor="middle">d5</text><rect x="161.0" y="37.2" width="38.0" height="6.8" fill="#a8e6b0" opacity="0.85"/><text x="180.0" y="43" fill="#9aa3b8" font-size="7.5" text-anchor="middle">d6</text></svg></div>
<div class="mcard"><div class="mtitle">THE TWO SINKS</div><div class="mbody">Into 31: 162 doors, mean distance 3.9012 (+8.9% over the 148.75 baseline). Into 63: 141 doors, mean 4.0426 (−5.2%).</div><svg width="200" height="44" viewBox="0 0 200 44"><rect x="1.0" y="36.6" width="18.0" height="7.4" fill="#7dd3fc" opacity="0.85"/><text x="10.0" y="43" fill="#9aa3b8" font-size="7.5" text-anchor="middle">31→</text><rect x="21.0" y="18.8" width="18.0" height="25.2" fill="#7dd3fc" opacity="0.85"/><text x="30.0" y="43" fill="#9aa3b8" font-size="7.5" text-anchor="middle"></text><rect x="41.0" y="14.6" width="18.0" height="29.4" fill="#7dd3fc" opacity="0.85"/><text x="50.0" y="43" fill="#9aa3b8" font-size="7.5" text-anchor="middle"></text><rect x="61.0" y="29.3" width="18.0" height="14.7" fill="#7dd3fc" opacity="0.85"/><text x="70.0" y="43" fill="#9aa3b8" font-size="7.5" text-anchor="middle"></text><rect x="81.0" y="35.6" width="18.0" height="8.4" fill="#7dd3fc" opacity="0.85"/><text x="90.0" y="43" fill="#9aa3b8" font-size="7.5" text-anchor="middle"></text><rect x="101.0" y="38.0" width="18.0" height="6.0" fill="#7dd3fc" opacity="0.85"/><text x="110.0" y="43" fill="#9aa3b8" font-size="7.5" text-anchor="middle">63→</text><rect x="121.0" y="23.5" width="18.0" height="20.5" fill="#7dd3fc" opacity="0.85"/><text x="130.0" y="43" fill="#9aa3b8" font-size="7.5" text-anchor="middle"></text><rect x="141.0" y="12.0" width="18.0" height="32.0" fill="#7dd3fc" opacity="0.85"/><text x="150.0" y="43" fill="#9aa3b8" font-size="7.5" text-anchor="middle"></text><rect x="161.0" y="27.1" width="18.0" height="16.9" fill="#7dd3fc" opacity="0.85"/><text x="170.0" y="43" fill="#9aa3b8" font-size="7.5" text-anchor="middle"></text><rect x="181.0" y="34.3" width="18.0" height="9.7" fill="#7dd3fc" opacity="0.85"/><text x="190.0" y="43" fill="#9aa3b8" font-size="7.5" text-anchor="middle"></text></svg></div>
<div class="mcard"><div class="mtitle">THE TOLLBOOTH — GEM 17</div><div class="mbody">Hall = sink = 134 at the low-bit popcount-2 masks {3, 5, 9} — 402 doors through three gates. The high-bit twins {17, 33, 65} run 155. Popcount alone does not set the toll; position does.</div><svg width="200" height="44" viewBox="0 0 200 44"><rect x="1.0" y="16.3" width="31.3" height="27.7" fill="#ffcf8a" opacity="0.85"/><text x="16.7" y="43" fill="#9aa3b8" font-size="7.5" text-anchor="middle">3</text><rect x="34.3" y="16.3" width="31.3" height="27.7" fill="#ffcf8a" opacity="0.85"/><text x="50.0" y="43" fill="#9aa3b8" font-size="7.5" text-anchor="middle">5</text><rect x="67.7" y="16.3" width="31.3" height="27.7" fill="#ffcf8a" opacity="0.85"/><text x="83.3" y="43" fill="#9aa3b8" font-size="7.5" text-anchor="middle">9</text><rect x="101.0" y="12.0" width="31.3" height="32.0" fill="#ffcf8a" opacity="0.85"/><text x="116.7" y="43" fill="#9aa3b8" font-size="7.5" text-anchor="middle">17</text><rect x="134.3" y="12.0" width="31.3" height="32.0" fill="#ffcf8a" opacity="0.85"/><text x="150.0" y="43" fill="#9aa3b8" font-size="7.5" text-anchor="middle">33</text><rect x="167.7" y="12.0" width="31.3" height="32.0" fill="#ffcf8a" opacity="0.85"/><text x="183.3" y="43" fill="#9aa3b8" font-size="7.5" text-anchor="middle">65</text></svg></div>
<div class="mcard"><div class="mtitle">KIRCHHOFF — THE BALANCE LAW</div><div class="mbody">At every one of the 48 nodes, hallways in = sink doors out. Δ = 0 × 48, no exceptions. Pair-membership = hall + sink (node 31: 324 = 162 + 162; 648 appearances, the maximum).</div></div>
<div class="mcard"><div class="mtitle">SPECTRUM W — PAIR ADJACENCY</div><div class="mbody">λmax 299.358 · λmin −129.871 (×3) · Σλ² = 191,808 (Frobenius closes) · 27 distinct eigenvalues · smallest |λ| ≈ 0.059 — invertible, barely.</div><svg width="200" height="44" viewBox="0 0 200 44"><rect x="1.0" y="12.0" width="10.5" height="32.0" fill="#7dd3fc" opacity="0.85"/><rect x="13.5" y="39.1" width="10.5" height="4.9" fill="#7dd3fc" opacity="0.85"/><rect x="26.0" y="39.1" width="10.5" height="4.9" fill="#7dd3fc" opacity="0.85"/><rect x="38.5" y="39.1" width="10.5" height="4.9" fill="#7dd3fc" opacity="0.85"/><rect x="51.0" y="39.2" width="10.5" height="4.8" fill="#7dd3fc" opacity="0.85"/><rect x="63.5" y="39.3" width="10.5" height="4.7" fill="#7dd3fc" opacity="0.85"/><rect x="76.0" y="39.3" width="10.5" height="4.7" fill="#7dd3fc" opacity="0.85"/><rect x="88.5" y="40.5" width="10.5" height="3.5" fill="#7dd3fc" opacity="0.85"/><rect x="101.0" y="40.5" width="10.5" height="3.5" fill="#7dd3fc" opacity="0.85"/><rect x="113.5" y="40.5" width="10.5" height="3.5" fill="#7dd3fc" opacity="0.85"/><rect x="126.0" y="40.5" width="10.5" height="3.5" fill="#7dd3fc" opacity="0.85"/><rect x="138.5" y="40.9" width="10.5" height="3.1" fill="#7dd3fc" opacity="0.85"/><rect x="151.0" y="41.5" width="10.5" height="2.5" fill="#7dd3fc" opacity="0.85"/><rect x="163.5" y="41.5" width="10.5" height="2.5" fill="#7dd3fc" opacity="0.85"/><rect x="176.0" y="41.5" width="10.5" height="2.5" fill="#7dd3fc" opacity="0.85"/><rect x="188.5" y="42.5" width="10.5" height="1.5" fill="#7dd3fc" opacity="0.85"/></svg></div>
<div class="mcard"><div class="mtitle">SPECTRUM T — TRANSITION</div><div class="mbody">The second operator, measured separately and never conflated: λmax 598.650 · λmin −86.262 · Σλ² = 685,584 · 28,560 entries = 4 × 7,140.</div></div>
<div class="mcard"><div class="mtitle">FLOW CENSUS — THE RIVER LEDGER</div><div class="mbody">12,528 = 7,140 doors + 2,256 self-touching + 502 bottom exits + 2,630 top exits. Every transition accounted for; nothing leaves uncounted.</div><svg width="200" height="44" viewBox="0 0 200 44"><rect x="1.0" y="12.0" width="48.0" height="32.0" fill="#d8b4fe" opacity="0.85"/><text x="25.0" y="43" fill="#9aa3b8" font-size="7.5" text-anchor="middle">DOORS</text><rect x="51.0" y="33.9" width="48.0" height="10.1" fill="#d8b4fe" opacity="0.85"/><text x="75.0" y="43" fill="#9aa3b8" font-size="7.5" text-anchor="middle">SELF</text><rect x="101.0" y="32.2" width="48.0" height="11.8" fill="#d8b4fe" opacity="0.85"/><text x="125.0" y="43" fill="#9aa3b8" font-size="7.5" text-anchor="middle">TOP</text><rect x="151.0" y="41.8" width="48.0" height="2.2" fill="#d8b4fe" opacity="0.85"/><text x="175.0" y="43" fill="#9aa3b8" font-size="7.5" text-anchor="middle">BOTTOM</text></svg></div>
<div class="mcard"><div class="mtitle">H₁₄ — THE SECOND CONSTRUCTION</div><div class="mbody">Every column weighs exactly 8 of 14. Pair syndrome distribution 124/282/352/253/100/17 at weights 2–12 — the pair distances, doubled. Minimum weight 2 → 0 collisions in 1,128, by a second independent route.</div><svg width="200" height="44" viewBox="0 0 200 44"><rect x="1.0" y="32.7" width="31.3" height="11.3" fill="#a8e6b0" opacity="0.85"/><text x="16.7" y="43" fill="#9aa3b8" font-size="7.5" text-anchor="middle">w2</text><rect x="34.3" y="18.4" width="31.3" height="25.6" fill="#a8e6b0" opacity="0.85"/><text x="50.0" y="43" fill="#9aa3b8" font-size="7.5" text-anchor="middle">w4</text><rect x="67.7" y="12.0" width="31.3" height="32.0" fill="#a8e6b0" opacity="0.85"/><text x="83.3" y="43" fill="#9aa3b8" font-size="7.5" text-anchor="middle">w6</text><rect x="101.0" y="21.0" width="31.3" height="23.0" fill="#a8e6b0" opacity="0.85"/><text x="116.7" y="43" fill="#9aa3b8" font-size="7.5" text-anchor="middle">w8</text><rect x="134.3" y="34.9" width="31.3" height="9.1" fill="#a8e6b0" opacity="0.85"/><text x="150.0" y="43" fill="#9aa3b8" font-size="7.5" text-anchor="middle">w10</text><rect x="167.7" y="42.5" width="31.3" height="1.5" fill="#a8e6b0" opacity="0.85"/><text x="183.3" y="43" fill="#9aa3b8" font-size="7.5" text-anchor="middle">w12</text></svg></div>
<div class="mcard"><div class="mtitle">THE LYNCHPIN GEOMETRY</div><div class="mbody">53.130102° = arctan(4/3) · stagger 38.0° · loop 15.130102° — and 53.130102 − 38 = 15.130102 exactly. One angle organizes the spiral, the desk line, and the rotation R = (1/5)[[3,−4],[4,3]].</div></div>
<div class="mcard"><div class="mtitle">QUADS & MIDPOINTS</div><div class="mbody">The doors fold into exactly 1,785 quads under ★ symmetry (7,140 / 4). Pair sums take 83 distinct midpoints, 16 to 184 — every zero of the residual map sits on the balance line.</div></div>
<div class="mcard"><div class="mtitle">THE PLATES — AN OUTSIDE EYE</div><div class="mbody">Ten external renderings, graded claim by claim: 54 of 56 verified exact = 96.4% fidelity. The 2 false: “3,384 Wider” (true 3,584) and “46 Odd Masks” (true 48), both on one plate.</div></div>
<div class="mcard"><div class="mtitle">FRACTAL DIMENSIONS — THE ART, MEASURED</div><div class="mbody">Box-counting D: kaleidoscope mirror 1.756 · the merge 1.688 · ZERO pinpoint 1.633 · the Fool 1.506. Slice rhythm runs through every piece (autocorrelation 0.48–0.88); the Scan Fool ticks at 11.33 px, 0.884.</div><svg width="200" height="44" viewBox="0 0 200 44"><rect x="1.0" y="12.0" width="48.0" height="32.0" fill="#ffcf8a" opacity="0.85"/><text x="25.0" y="43" fill="#9aa3b8" font-size="7.5" text-anchor="middle">MIRROR</text><rect x="51.0" y="13.2" width="48.0" height="30.8" fill="#ffcf8a" opacity="0.85"/><text x="75.0" y="43" fill="#9aa3b8" font-size="7.5" text-anchor="middle">MERGE</text><rect x="101.0" y="14.2" width="48.0" height="29.8" fill="#ffcf8a" opacity="0.85"/><text x="125.0" y="43" fill="#9aa3b8" font-size="7.5" text-anchor="middle">ZERO</text><rect x="151.0" y="16.6" width="48.0" height="27.4" fill="#ffcf8a" opacity="0.85"/><text x="175.0" y="43" fill="#9aa3b8" font-size="7.5" text-anchor="middle">FOOL</text></svg></div>
<div class="mcard"><div class="mtitle">LIGHT, MEASURED — FOOLS PERSPECTIVE</div><div class="mbody">One constant source behind the viewer; shadows fall north: Fool 77.8° · Fiddler 87.5° · Table 68.1° · mirror 88°. Strongest shimmer: the Table, 0.43%. Figure-span law 0.60 (Fiddler verified 0.575). The Fool is 208 layers thick — the layer count is the mass. Desk line v2: 52.97°, within 0.16° of the lynchpin; the fixed synthesis sits at 45.72°, 7.41° off — recorded, not forgiven.</div></div>
<div class="mcard"><div class="mtitle">THE VAULT REGISTER</div><div class="mbody">1,545 filings sealed 7/7: 1,017 admitted · 522 reflected · 5 held · 1 refused (the carved-out video, failing slice: GATE). Emblem centroid (0.502, 0.489); waist pinch at y = 0.384.</div></div>
<div class="mcard"><div class="mtitle">THE FROZEN DRIVE</div><div class="mbody">3,696 items · 4.97 GB · one month (Sep 2026) holds 35.7% of everything. By hash, 38.5% of all bytes are redundant copies — one PDF exists five times, byte-identical, 853 MB of echo.</div></div>
