                  .map(e => [e, (pr[e[0]].Z + pr[e[1]].Z) / 2]).sort((a, b) => b[1] - a[1]);
  if (S.estyle === 'dash') ctx.setLineDash([4, 5]);
  ctx.lineDashOffset = -t * 24;
  for (const [e] of es){
    const A = pr[e[0]], B = pr[e[1]];
    if (S.xray && (A.Z > 0.05 || B.Z > 0.05)) continue;
    const hot = sel && (e[0] === sel || e[1] === sel);
    ctx.beginPath(); ctx.moveTo(A.X, A.Y);
    if (S.estyle === 'arc'){ const mx = (A.X + B.X) / 2, my = (A.Y + B.Y) / 2; const dx = mx - W/2, dy = my - H/2; ctx.quadraticCurveTo(mx + dx * 0.22, my + dy * 0.22, B.X, B.Y); }
    else ctx.lineTo(B.X, B.Y);
    ctx.strokeStyle = S.ecolor === 'dist' ? distCol(e[2], t, e[0]) : S.ecolor === 'heat' ? heatCol(e[3] / 28) : (SCH.acc);
    ctx.globalAlpha = (0.045 + Math.min(e[3], 28) / 55) * (0.5 + 0.5 * A.F) + (hot ? 0.5 : 0);
    if (sel && !hot) ctx.globalAlpha *= 0.25;
    ctx.lineWidth = hot ? 1.5 : 0.7; ctx.stroke();
  }
  ctx.setLineDash([]);
  if (S.pulsesOn) for (const pu of pulses){
    pu.ph = (pu.ph + pu.sp * 0.016 * S.speed * R) % 1;
    const a = BYM[pu.e[0]], b = BYM[pu.e[1]];
    const from = a.sink >= b.sink ? pr[b.m] : pr[a.m], to = a.sink >= b.sink ? pr[a.m] : pr[b.m];
    const X = from.X + (to.X - from.X) * pu.ph, Y = from.Y + (to.Y - from.Y) * pu.ph;
    ctx.globalAlpha = 0.85 * Math.sin(pu.ph * Math.PI);
    ctx.drawImage(sprFor(SCH.acc), X - 7, Y - 7, 14, 14);
  }
  ctx.globalCompositeOperation = 'source-over'; ctx.globalAlpha = 1;
  const ns = P3.map(p => [p, pr[p.m], curPos(p)]).sort((a, b) => b[1].Z - a[1].Z);
  for (const [p, q, c3] of ns){
    if (S.xray && q.Z > 0.05) continue;
    const big = p.m === 31 || p.m === 63;
    const r = (big ? 15 : 9.5) * q.F * (sel === p.m ? 1.8 : 1) * S.nsize * S.glow;
    const col = nodeCol(p, t);
    ctx.globalAlpha = (0.5 + 0.5 * q.F) * (S.focus && q.Z > 0.05 ? 0.30 : 1);
    if (S.nshape === 'glow') ctx.drawImage(sprFor(col), q.X - r, q.Y - r, r * 2, r * 2);
    else if (S.nshape === 'octa'){
      const rr = r * 0.62, top = projXYZ(c3[0], c3[1] + 0.09, c3[2], t), bot = projXYZ(c3[0], c3[1] - 0.09, c3[2], t);
      ctx.strokeStyle = col; ctx.lineWidth = 1.1;
      ctx.beginPath(); ctx.moveTo(q.X, q.Y - rr); ctx.lineTo(q.X + rr, q.Y); ctx.lineTo(q.X, q.Y + rr); ctx.lineTo(q.X - rr, q.Y); ctx.closePath(); ctx.stroke();
      ctx.beginPath(); ctx.moveTo(top.X, top.Y); ctx.lineTo(q.X + rr, q.Y); ctx.moveTo(top.X, top.Y); ctx.lineTo(q.X - rr, q.Y); ctx.moveTo(bot.X, bot.Y); ctx.lineTo(q.X + rr, q.Y); ctx.moveTo(bot.X, bot.Y); ctx.lineTo(q.X - rr, q.Y); ctx.stroke();
    }
    else {
      ctx.strokeStyle = col; ctx.fillStyle = col; ctx.lineWidth = 1.6;
      ctx.beginPath();
      if (S.nshape === 'ring') ctx.arc(q.X, q.Y, r * 0.55, 0, 7);
      else if (S.nshape === 'diamond'){ ctx.moveTo(q.X, q.Y - r * 0.6); ctx.lineTo(q.X + r * 0.6, q.Y); ctx.lineTo(q.X, q.Y + r * 0.6); ctx.lineTo(q.X - r * 0.6, q.Y); ctx.closePath(); }
      else { ctx.font = Math.round(r * 1.5) + 'px Georgia'; ctx.textAlign = 'center'; ctx.fillText('★', q.X, q.Y + r * 0.5); }
      if (S.nshape !== 'star') ctx.stroke();
    }
    ctx.globalAlpha = 1;
    const showLabel = S.label === 'all' || S.label === 'binary' || (S.label === 'sinks' && (big || sel === p.m));
    if (showLabel){ ctx.fillStyle = SCH.light ? '#333' : '#e8e6df'; ctx.font = '11px ui-monospace, Menlo, monospace'; ctx.textAlign = 'center'; ctx.fillText(S.label === 'binary' ? p.m.toString(2).padStart(7, '0') : p.m, q.X, q.Y - r - 4); }
  }
  // ---- MIRROR FLOOR: wire grid at y = -1.35 with the manifold reflected in it
  if (S.floor){
    const fy = -1.35;
    ctx.strokeStyle = SCH.mesh; ctx.lineWidth = 0.6;
    for (let g = -4; g <= 4; g++){
      let a = projXYZ(g * 0.4, fy, -1.6, t), b = projXYZ(g * 0.4, fy, 1.6, t);
      ctx.globalAlpha = 0.20; ctx.beginPath(); ctx.moveTo(a.X, a.Y); ctx.lineTo(b.X, b.Y); ctx.stroke();
      a = projXYZ(-1.6, fy, g * 0.4, t); b = projXYZ(1.6, fy, g * 0.4, t);
      ctx.beginPath(); ctx.moveTo(a.X, a.Y); ctx.lineTo(b.X, b.Y); ctx.stroke();
    }
    ctx.globalAlpha = 1;
    for (const [p] of ns){
      const c = curPos(p); const q = projXYZ(c[0], 2 * fy - c[1], c[2], t);
      ctx.globalAlpha = 0.15; const r = 9.5 * q.F * S.nsize;
      ctx.drawImage(sprFor(nodeCol(p, t)), q.X - r, q.Y - r, r * 2, r * 2);
    }
    ctx.globalAlpha = 1;
  }
  // ---- CORE SOLID: a platonic wireframe turning inside the ZERO
  if (S.core !== 'off'){
    const sol = SOLIDS[S.core], a1 = -coreAng, a2 = coreAng * RDEN / RNUM;
    const sp = sol.v.map(v => {
      let [x, y, z] = v.map(u => u * 0.30);
      let X = x * Math.cos(a1) - z * Math.sin(a1), Z = x * Math.sin(a1) + z * Math.cos(a1);
      let Y = y * Math.cos(a2) - Z * Math.sin(a2); Z = y * Math.sin(a2) + Z * Math.cos(a2);
      return projXYZ(X, Y, Z, t);
    });
    ctx.strokeStyle = SCH.acc; ctx.globalAlpha = 0.85; ctx.lineWidth = 1.1;
    for (const [i, j] of sol.e){ ctx.beginPath(); ctx.moveTo(sp[i].X, sp[i].Y); ctx.lineTo(sp[j].X, sp[j].Y); ctx.stroke(); }
    ctx.globalAlpha = 1;
  }
  // ---- selection reticle + leader wire to the hub
  if (sel && pr[sel]){
    const q = pr[sel], rr = 22 + 3 * Math.sin(t * 3), a0 = t * 0.9;
    ctx.strokeStyle = SCH.acc; ctx.lineWidth = 1.4;
    for (let k = 0; k < 4; k++){
      const a = a0 + k * Math.PI / 2;
      ctx.beginPath(); ctx.arc(q.X, q.Y, rr, a, a + 0.7); ctx.stroke();
    }
    ctx.setLineDash([3, 5]); ctx.globalAlpha = 0.55; ctx.beginPath(); ctx.moveTo(W/2, H/2); ctx.lineTo(q.X, q.Y); ctx.stroke(); ctx.setLineDash([]); ctx.globalAlpha = 1;
    if (S.aber){
      const spr = sprFor(nodeCol(BYM[sel], t));
      ctx.globalCompositeOperation = 'lighter';
      ctx.globalAlpha = 0.5; ctx.drawImage(sprFor('#ff2a3c'), q.X - 16, q.Y - 13.5, 27, 27);
      ctx.drawImage(sprFor('#2affd8'), q.X - 11, q.Y - 13.5, 27, 27);
      ctx.globalCompositeOperation = 'source-over'; ctx.globalAlpha = 1;
    }
  }
  ctx.beginPath(); ctx.arc(W/2, H/2, 16 + 2.2 * Math.sin(t * 2), 0, 7); ctx.strokeStyle = SCH.acc; ctx.lineWidth = 2; ctx.stroke();
  ctx.beginPath(); ctx.arc(W/2, H/2, 24 + 3 * Math.sin(t * 2 + 1), 0, 7); ctx.strokeStyle = SCH.acc; ctx.globalAlpha = 0.35; ctx.lineWidth = 1; ctx.stroke(); ctx.globalAlpha = 1;
  ctx.fillStyle = SCH.light ? '#333' : '#f3e9c8'; ctx.font = '18px Georgia'; ctx.textAlign = 'center'; ctx.fillText('★', W/2, H/2 + 6.5);
  if (wave >= 0){
    const wr = wave * Math.min(W, H) * 0.52; wave += 0.016;
    ctx.beginPath(); ctx.arc(W/2, H/2, wr, 0, 7); ctx.strokeStyle = SCH.acc; ctx.globalAlpha = Math.max(0, 0.8 - wave); ctx.lineWidth = 2.5; ctx.stroke(); ctx.globalAlpha = 1;
    if (wave > 1.15) wave = -1;
  }
  for (let i = ripples.length - 1; i >= 0; i--){
    const rp = ripples[i]; rp.r += 3.2; rp.a -= 0.03;
    if (rp.a <= 0){ ripples.splice(i, 1); continue; }
    ctx.beginPath(); ctx.arc(rp.x, rp.y, rp.r, 0, 7); ctx.strokeStyle = SCH.acc; ctx.globalAlpha = rp.a; ctx.lineWidth = 1.5; ctx.stroke(); ctx.globalAlpha = 1;
  }
  ctx.restore();
  if (S.pupil){
    pupilR += ((Math.min(W, H) * 0.46) - pupilR) * 0.06;
    pupilKick *= 0.94;
    const R = Math.max(40, pupilR * (1 - 0.16 * pupilKick) + Math.sin(t * 0.8) * 3);
    if (S.purk){
      const gx = W/2 - R * 0.38, gy = H/2 - R * 0.42;
      const gr = ctx.createRadialGradient(gx, gy, 0, gx, gy, R * 0.5);
      gr.addColorStop(0, 'rgba(255,255,255,0.20)'); gr.addColorStop(1, 'rgba(255,255,255,0)');
      ctx.fillStyle = gr; ctx.beginPath(); ctx.arc(W/2, H/2, R, 0, 7); ctx.fill();
      ctx.fillStyle = 'rgba(243,233,200,0.35)'; ctx.font = '13px Georgia'; ctx.textAlign = 'center';
      ctx.fillText('★', gx, gy + 4);
    }
    if (S.scat){
      const gr2 = ctx.createRadialGradient(W/2, H/2, R * 0.2, W/2, H/2, R);
      gr2.addColorStop(0, 'rgba(90,140,255,0)'); gr2.addColorStop(1, 'rgba(90,140,255,0.20)');
      ctx.fillStyle = gr2; ctx.beginPath(); ctx.arc(W/2, H/2, R, 0, 7); ctx.fill();
    }
    // the world outside the pupil does not arrive
    ctx.beginPath(); ctx.rect(0, 0, W, H); ctx.arc(W/2, H/2, R, 0, 7);
    ctx.fillStyle = '#000'; ctx.fill('evenodd');
    // iris: woven rings of amber and umber around the hole
    for (let k = 0; k < 5; k++){
      ctx.beginPath(); ctx.arc(W/2, H/2, R + 3 + k * 5, 0, 7);
      ctx.strokeStyle = ['#6b4a1f', '#8a5f27', '#54380f', '#a8762f', '#3d2708'][k];
      ctx.globalAlpha = 0.85 - k * 0.13; ctx.lineWidth = 4.5; ctx.stroke();
    }
    ctx.globalAlpha = 1;
    ctx.fillStyle = '#c9b18a'; ctx.font = '11px ui-monospace, monospace'; ctx.textAlign = 'center';
    ctx.fillText('THE PUPIL — Ø 2–8 MM · EVERY ANGLE YOU HAVE EVER MEASURED ENTERED HERE', W/2, H/2 + R + 42);
  }
  if (S.ribbon){
    const bw = W / 48, baseY = H - 160;
    ctx.fillStyle = SCH.light ? 'rgba(238,234,222,0.85)' : 'rgba(5,8,18,0.85)'; ctx.fillRect(0, baseY - 78, W, 74);
    ctx.strokeStyle = SCH.acc; ctx.globalAlpha = 0.4; ctx.beginPath(); ctx.moveTo(0, baseY - 40); ctx.lineTo(W, baseY - 40); ctx.stroke(); ctx.globalAlpha = 1;
    SPEC.forEach((v, i) => { const hh = Math.abs(v) / 300 * 36; ctx.fillStyle = v >= 0 ? '#7dd3fc' : '#ff9d8a'; ctx.fillRect(i * bw + 1, v >= 0 ? baseY - 40 - hh : baseY - 40, bw - 2, hh); });
    ctx.fillStyle = SCH.light ? '#333' : '#9aa3b8'; ctx.font = '10px ui-monospace, monospace'; ctx.textAlign = 'left';
    ctx.fillText('W SPECTRUM — 48 EIGENVALUES · λmax 299.358 · λmin −129.871', 8, baseY - 66);
  }
  const res = resonance(t);
  SIG_HIST.push(res); if (SIG_HIST.length > 75) SIG_HIST.shift();
  const sc = document.getElementById('spark').getContext('2d');
  sc.clearRect(0, 0, 150, 30); sc.beginPath();
  SIG_HIST.forEach((v, i) => { const X = i * 2, Y = 29 - v * 30; i ? sc.lineTo(X, Y) : sc.moveTo(X, Y); });
  sc.strokeStyle = SCH.acc; sc.lineWidth = 1.2; sc.stroke();
  document.getElementById('hud').textContent =
    '[ TOPOLOGICAL MANIFOLD : DOOR SYSTEM ]\n[ HARMONIC RESONANCE (Σ): ' + res.toFixed(4) + ' ]\n[ ISOMETRIC ROTATION (θ): ' + ((rotY * 180 / Math.PI) % 360).toFixed(1) + '° ]\n[ FPS: ' + fpsEMA.toFixed(0) + ' · ' + S.layout.toUpperCase() + ' · '  + es.length + ' EDGES SHOWN ]\n[ DEFAULT : MEASURED UNIVERSE · SPEED ' + RNUM + ':' + RDEN + ' · CONSTANT-WIDTH SHAPE ]';
  requestAnimationFrame(frame);
}
requestAnimationFrame(frame);
setTimeout(() => { const b = document.getElementById('boot'); b.style.opacity = '0'; setTimeout(() => b.remove(), 750); }, 1500);

function showReadout(p){
  const ro = document.getElementById('readout');
  ro.style.display = 'block';
  ro.innerHTML = '<b>Node ' + p.m + '</b> — popcount ' + p.pc + ' · hall ' + p.hall + ' = sink ' + p.sink +
    ' · pair-membership ' + p.pairm + ' · appearances ' + p.appear +
    '<div class="bar2" style="width:' + Math.round(p.appear / 648 * 100) + '%"></div>' +
    '<span style="font-size:12px;color:#9aa3b8">appearances vs node 31 (648, the maximum)</span>';
}
// ---- controls
function group(name, fn){ document.querySelectorAll('[data-' + name + ']').forEach(b => b.addEventListener('click', () => { document.querySelectorAll('[data-' + name + ']').forEach(x => x.classList.remove('on')); b.classList.add('on'); fn(b.dataset[name]); haptic(1); })); }
group('layout', v => { layFrom = {}; P3.forEach(p => layFrom[p.m] = curPos(p)); S.layout = v; layK = 0; lastAct = performance.now(); });
group('scheme', v => { SCH = SCHEMES[v]; document.body.style.background = SCH.bg; });
group('estyle', v => S.estyle = v);
group('ecolor', v => S.ecolor = v);
group('cls', v => S.cls = v);
group('nshape', v => S.nshape = v);
group('label', v => S.label = v);
group('mesh', v => S.mesh = v);
function tog(id, key, fn){ const b = document.getElementById(id); b.addEventListener('click', () => { S[key] = !S[key]; b.classList.toggle('on', S[key]); if (fn) fn(); haptic(1); }); }
tog('neverBtn', 'never'); tog('starsBtn', 'stars'); tog('pulsesBtn', 'pulsesOn'); tog('xrayBtn', 'xray');
tog('ribbonBtn', 'ribbon'); tog('tumbleBtn', 'tumble'); tog('revBtn', 'rev'); tog('hapBtn', 'hap');
tog('spinBtn', 'spin');
document.getElementById('tourBtn').addEventListener('click', e => {
  if (tourI >= 0){ tourI = -1; e.target.classList.remove('on'); e.target.textContent = 'TOUR THE SINKS'; }
  else { tourI = 0; tourTimer = 0; e.target.classList.add('on'); e.target.textContent = 'STOP TOUR'; }
  haptic(2);
});
group('skin', v => S.skin = v);
const CORES = ['octa', 'tetra', 'icosa', 'off'];
document.getElementById('coreBtn').addEventListener('click', e => {
  const nx = CORES[(CORES.indexOf(S.core) + 1) % CORES.length]; S.core = nx;
  e.target.textContent = 'Core: ' + (nx === 'off' ? 'none' : nx === 'octa' ? 'octahedron' : nx === 'tetra' ? 'tetrahedron' : 'icosahedron');
  haptic(1);
});
tog('deformBtn', 'deform'); tog('cageBtn', 'cage'); tog('floorBtn', 'floor'); tog('spokesBtn', 'spokes'); tog('focusBtn', 'focus'); tog('aberBtn', 'aber');
document.getElementById('crtBtn').addEventListener('click', e => {
  S.crt = !S.crt; e.target.classList.toggle('on', S.crt);
  document.getElementById('crt').style.display = S.crt ? 'block' : 'none';
  document.getElementById('vig').style.display = S.crt ? 'block' : 'none';
  haptic(1);
});
const SHOWSEQ = [['spectrum','sph'],['iridescent','strata'],['thermal','sph'],['gold','flat'],['blueprint','ring'],['paper','flat']];
document.getElementById('showBtn').addEventListener('click', e => {
  showcase = !showcase; e.target.classList.toggle('on', showcase);
  if (showcase){
    let i = 0;
    const step = () => { if (!showcase) return; const [sch, lay] = SHOWSEQ[i++ % SHOWSEQ.length];
      SCH = SCHEMES[sch]; document.querySelectorAll('[data-scheme]').forEach(x => x.classList.toggle('on', x.dataset.scheme === sch));
      layFrom = {}; P3.forEach(p => layFrom[p.m] = curPos(p)); S.layout = lay; layK = 0;
      document.querySelectorAll('[data-layout]').forEach(x => x.classList.toggle('on', x.dataset.layout === lay)); };
    step(); showcaseTimer = setInterval(step, 6000);
  } else clearInterval(showcaseTimer);
  haptic(2);
});
cv.addEventListener('pointerdown', () => { if (showcase){ showcase = false; clearInterval(showcaseTimer); document.getElementById('showBtn').classList.remove('on'); } }, true);
tog('pupilBtn', 'pupil', () => { if (S.pupil){ document.getElementById('deck').classList.add('open'); } });
tog('refrBtn', 'refr', () => { if (S.refr && !S.pupil){ S.pupil = true; document.getElementById('pupilBtn').classList.add('on'); } });
tog('scatBtn', 'scat', () => { if (S.scat && !S.pupil){ S.pupil = true; document.getElementById('pupilBtn').classList.add('on'); } });
tog('purkBtn', 'purk', () => { if (S.purk && !S.pupil){ S.pupil = true; document.getElementById('pupilBtn').classList.add('on'); } });
tog('invBtn', 'invert');
document.getElementById('deckBtn').addEventListener('click', e => {
  const d = document.getElementById('deck'); d.classList.toggle('open');
  e.target.textContent = d.classList.contains('open') ? '◉ EVERYTHING MEASURED — OPEN' : '◉ EVERYTHING MEASURED';
  haptic(1);
});
document.getElementById('resetBtn').addEventListener('click', () => { zoom = 1; rotY = 0.6; rotX = 0.35; sel = null; document.getElementById('readout').style.display = 'none'; haptic(2); });
document.getElementById('trayBtn').addEventListener('click', e => { const tr = document.getElementById('tray'); tr.classList.toggle('hidden'); e.target.textContent = tr.classList.contains('hidden') ? 'VISUAL CONTROLS ▴' : 'VISUAL CONTROLS ▾'; });
document.getElementById('nsize').addEventListener('input', e => S.nsize = e.target.value / 100);
document.getElementById('trails').addEventListener('input', e => S.trails = e.target.value / 100);
document.getElementById('glowr').addEventListener('input', e => S.glow = e.target.value / 100);
document.getElementById('speed').addEventListener('input', e => S.speed = e.target.value / 100);

// ---- canvas interaction
let drag = null, pinch = null;
function touchHub(e){ return Math.hypot(e.clientX - W/2, e.clientY - H/2) < 44; }
cv.addEventListener('pointerdown', e => { lastAct = performance.now(); if (S.pupil) pupilKick = 1; ripples.push({x: e.clientX, y: e.clientY, r: 4, a: 0.7}); drag = {p: [e.clientX, e.clientY], moved: 0, hub: touchHub(e)}; cv.setPointerCapture(e.pointerId); });
cv.addEventListener('pointermove', e => {
  if (!drag) return; lastAct = performance.now();
  const dx = e.clientX - drag.p[0], dy = e.clientY - drag.p[1];
  drag.moved += Math.abs(dx) + Math.abs(dy); drag.p = [e.clientX, e.clientY];
  if (drag.moved > 4 && !drag.hub){ gT = null; if (tourI >= 0) tourI = -1; rotY += dx * 0.008; rotX = Math.max(-1.4, Math.min(1.4, rotX + dy * 0.008)); }
});
cv.addEventListener('pointerup', e => {
  const wasTap = drag && drag.moved <= 4, wasHub = drag && drag.hub; drag = null; lastAct = performance.now();
  if (!wasTap) return;
  if (wasHub){ wave = 0; haptic(2); return; }
  const t = (performance.now() - t0) / 1000; let best = null, bd = 27;
  for (const p of P3){ const c = curPos(p); const q = projXYZ(c[0], c[1], c[2], t); const d = Math.hypot(q.X - e.clientX, q.Y - e.clientY); if (d < bd){ bd = d; best = p; } }
  if (best){ sel = best.m; haptic(1); showReadout(best); }
  else { sel = null; document.getElementById('readout').style.display = 'none'; }
});
cv.addEventListener('wheel', e => { e.preventDefault(); zoom = Math.min(2.6, Math.max(0.45, zoom * (e.deltaY < 0 ? 1.09 : 0.92))); }, {passive: false});
cv.addEventListener('touchstart', e => { if (e.touches.length === 2) pinch = Math.hypot(e.touches[0].clientX - e.touches[1].clientX, e.touches[0].clientY - e.touches[1].clientY); }, {passive: true});
cv.addEventListener('touchmove', e => { if (e.touches.length === 2 && pinch){ const d = Math.hypot(e.touches[0].clientX - e.touches[1].clientX, e.touches[0].clientY - e.touches[1].clientY); zoom = Math.min(2.6, Math.max(0.45, zoom * d / pinch)); pinch = d; lastAct = performance.now(); } }, {passive: true});

// ---- gyro
const state = document.getElementById('state');
function onOrient(e){
  if (!gyro.live){ gyro.live = true; haptic(2); }
  gyro.head = e.webkitCompassHeading != null ? e.webkitCompassHeading : (e.alpha != null ? 360 - e.alpha : 0);
  gyro.beta = e.beta || 0; gyro.gamma = e.gamma || 0;
  gT = {y: gyro.head * Math.PI / 180, x: Math.max(-1.4, Math.min(1.4, (gyro.beta - 40) * Math.PI / 180)), z: Math.max(-0.5, Math.min(0.5, -gyro.gamma * Math.PI / 360))};
  state.textContent = 'GYRO LIVE — heading ' + gyro.head.toFixed(0) + '° · β ' + gyro.beta.toFixed(0) + '° · γ ' + gyro.gamma.toFixed(0) + '° (frame rolls with γ)';
}
document.getElementById('gyroBtn').addEventListener('click', async () => {
  haptic(2); lastAct = performance.now();
  try {
    if (typeof DeviceOrientationEvent !== 'undefined' && typeof DeviceOrientationEvent.requestPermission === 'function'){
      const p = await DeviceOrientationEvent.requestPermission();
      if (p !== 'granted'){ state.textContent = 'GYRO DENIED — drag to orbit. (App viewer blocks sensors: long-press the file link → Open in Safari.)'; return; }
    }
    if (typeof DeviceOrientationEvent === 'undefined'){ state.textContent = 'NO SENSOR — DESKTOP MODE: drag to orbit'; return; }
    addEventListener('deviceorientation', onOrient, true);
    state.textContent = 'GYRO ARMED — waiting for readings…';
    setTimeout(() => { if (!gyro.live) state.textContent = 'GYRO SILENT in this viewer — long-press the file link → Open in Safari for live sensors'; }, 2600);
  } catch(err){ state.textContent = 'GYRO UNAVAILABLE — drag to orbit'; }
});
